import { createClient } from "@/lib/supabase/client";
import { FeedEvent, FeedEventType } from "@/types/database";
import { DataError } from "@/lib/data/errors";
import type { FeedScope } from "@/lib/feedPolicy";

/** Activity generated by learning (Bible §18, §50). Never prose-required. */
export async function logFeedEvent(params: {
  eventType: FeedEventType;
  squadId?: string | null;
  problemTitle?: string | null;
  problemSlug?: string | null;
  difficulty?: string | null;
  objectType?: string | null;
  objectId?: string | null;
  metadata?: Record<string, unknown>;
}): Promise<void> {
  const supabase = createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return;
  const { error } = await supabase.from("feed_events").insert({
    user_id: user.id,
    event_type: params.eventType,
    squad_id: params.squadId ?? null,
    problem_title: params.problemTitle ?? null,
    problem_slug: params.problemSlug?.toLowerCase() ?? null,
    difficulty: params.difficulty ?? null,
    object_type: params.objectType ?? null,
    object_id: params.objectId ?? null,
    metadata: params.metadata ?? {},
  });
  if (error) console.warn("logFeedEvent failed:", error.message);
}

/**
 * A feed row as §20 ranking returns it: the event plus why it ranked where it
 * did. `usefulness` is the undecayed §20 weight, `score` is usefulness after
 * recency decay — the UI shows the first and sorts by the second, so a person
 * can see that something old earned its place.
 */
export interface RankedFeedEvent extends Omit<FeedEvent, "actor"> {
  usefulness: number;
  score: number;
  /**
   * A deleted profile leaves the event in place — the row belongs to the
   * activity, not the account — so the actor is nullable here rather than
   * "must exist". "Someone deleted" is the honest rendering for that row.
   */
  actor?: { id: string; username: string; avatar_url: string | null } | null;
}

/**
 * Read one feed scope, ranked by §20.
 *
 * Ranking and the blocklist both happen in SQL (public.get_ranked_feed).
 * Filtering blocked authors in the client would still deliver their activity to
 * the device, which is not what "block" means to somebody who used it.
 */
export async function getRankedFeed(
  scope: Exclude<FeedScope, "platform">,
  opts: { squadId?: string | null; limit?: number } = {}
): Promise<RankedFeedEvent[]> {
  const supabase = createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();

  const { data, error } = await supabase.rpc("get_ranked_feed", {
    p_scope: scope,
    p_squad_id: opts.squadId ?? null,
    p_viewer: user?.id ?? null,
    p_limit: opts.limit ?? 30,
  });
  if (error) throw new DataError("feed", "Couldn't load feed. Retry.", { cause: error });

  // The RPC has no generated type, so the row is described here rather than
  // asserted: this is the only place that knows what get_ranked_feed returns.
  type RankedRow = Omit<RankedFeedEvent, "actor">;
  const rows = (data ?? []) as RankedRow[];
  if (rows.length === 0) return [];

  // One extra round trip rather than a join: PostgREST cannot join a table
  // that is not a declared relationship, and get_ranked_feed returns scalars.
  const ids = Array.from(new Set(rows.map((r) => r.user_id)));
  const { data: actors } = await supabase
    .from("profiles")
    .select("id, username, avatar_url")
    .in("id", ids);
  const byId = new Map((actors ?? []).map((a) => [a.id, a]));

  return rows.map((r) => ({ ...r, actor: byId.get(r.user_id) ?? null }));
}

export interface PlatformPost {
  id: string;
  kind: "contest" | "product" | "maintenance";
  title: string;
  body_md: string;
  href: string | null;
  pinned: boolean;
  created_at: string;
}

/** §19: Platform is announcements only. Separate from activity on purpose. */
export async function getPlatformPosts(limit = 20): Promise<PlatformPost[]> {
  const supabase = createClient();
  const { data, error } = await supabase
    .from("platform_posts")
    .select("id,kind,title,body_md,href,pinned,created_at")
    .order("pinned", { ascending: false })
    .order("created_at", { ascending: false })
    .limit(limit);
  if (error) throw new DataError("feed", "Couldn't load announcements. Retry.", { cause: error });
  return (data ?? []) as PlatformPost[];
}

export interface Discussion {
  id: string;
  author_id: string;
  problem_slug: string;
  pattern_tags: string[];
  body_md: string;
  squad_id: string | null;
  visibility: "squad" | "global";
  created_at: string;
  reply_count?: number;
  author?: { id: string; username: string; avatar_url: string | null } | null;
}

export interface DiscussionReply {
  id: string;
  discussion_id: string;
  author_id: string;
  body_md: string;
  created_at: string;
  author?: { id: string; username: string; avatar_url: string | null } | null;
}

/** Discussions for a scope, with reply counts — "meaningful discussion" (§20). */
export async function getDiscussions(
  opts: { problemSlug?: string | null; squadId?: string | null; limit?: number } = {}
): Promise<Discussion[]> {
  const supabase = createClient();
  let query = supabase
    .from("discussions")
    .select("id,author_id,problem_slug,pattern_tags,body_md,squad_id,visibility,created_at")
    .is("deleted_at", null)
    .order("created_at", { ascending: false })
    .limit(opts.limit ?? 20);
  if (opts.problemSlug) query = query.eq("problem_slug", opts.problemSlug);
  const { data, error } = await query;
  if (error) throw new DataError("feed", "Couldn't load discussions. Retry.", { cause: error });

  const rows = (data ?? []) as Omit<Discussion, "author" | "reply_count">[];
  if (rows.length === 0) return [];

  const counts = await replyCounts(rows.map((d) => d.id));
  const authors = await authorsFor(rows.map((d) => d.author_id));
  return rows.map((r) => ({
    ...r,
    reply_count: counts.get(r.id) ?? 0,
    author: authors.get(r.author_id) ?? null,
  }));
}

export async function getDiscussionReplies(discussionId: string): Promise<DiscussionReply[]> {
  const supabase = createClient();
  const { data, error } = await supabase
    .from("discussion_replies")
    .select("id,discussion_id,author_id,body_md,created_at")
    .eq("discussion_id", discussionId)
    .is("deleted_at", null)
    .order("created_at", { ascending: true })
    .limit(200);
  if (error) throw new DataError("feed", "Couldn't load replies. Retry.", { cause: error });
  const rows = (data ?? []) as DiscussionReply[];
  const authors = await authorsFor(rows.map((r) => r.author_id));
  return rows.map((r) => ({ ...r, author: authors.get(r.author_id) ?? null }));
}

async function replyCounts(ids: string[]): Promise<Map<string, number>> {
  const supabase = createClient();
  const out = new Map<string, number>();
  if (ids.length === 0) return out;
  const { data } = await supabase
    .from("discussion_replies")
    .select("discussion_id")
    .in("discussion_id", ids)
    .is("deleted_at", null);
  for (const r of (data ?? []) as { discussion_id: string }[]) {
    out.set(r.discussion_id, (out.get(r.discussion_id) ?? 0) + 1);
  }
  return out;
}

async function authorsFor(
  ids: string[]
): Promise<Map<string, { id: string; username: string; avatar_url: string | null }>> {
  const supabase = createClient();
  const unique = Array.from(new Set(ids));
  const out = new Map<string, { id: string; username: string; avatar_url: string | null }>();
  if (unique.length === 0) return out;
  const { data } = await supabase
    .from("profiles")
    .select("id, username, avatar_url")
    .in("id", unique);
  for (const a of (data ?? []) as { id: string; username: string; avatar_url: string | null }[]) {
    out.set(a.id, a);
  }
  return out;
}

/**
 * Create a discussion through the §51 gates.
 *
 * Errors come back from the database with messages written to be shown, so they
 * are surfaced verbatim rather than replaced with a generic failure. The
 * composer mirrors the same rules for instant feedback, but this is the answer
 * that counts.
 */
export async function createDiscussion(params: {
  problemSlug: string;
  patternTags: string[];
  body: string;
  visibility: "squad" | "global";
  squadId: string | null;
}): Promise<string> {
  const supabase = createClient();
  const { data, error } = await supabase.rpc("create_discussion", {
    p_problem_slug: params.problemSlug.toLowerCase(),
    p_pattern_tags: params.patternTags,
    p_body_md: params.body,
    p_visibility: params.visibility,
    p_squad_id: params.squadId,
  });
  if (error) throw new DataError("feed", error.message, { cause: error });
  return data as string;
}

export async function createDiscussionReply(
  discussionId: string,
  body: string
): Promise<string> {
  const supabase = createClient();
  const { data, error } = await supabase.rpc("create_discussion_reply", {
    p_discussion_id: discussionId,
    p_body_md: body,
  });
  if (error) throw new DataError("feed", error.message, { cause: error });
  return data as string;
}

/**
 * How many solves this person has *logged*.
 *
 * Deliberately not profiles.total_easy: that is the LeetCode-synced count of
 * easy problems, and the §51 Global gate counts rows in problem_events. Using
 * the wrong number would tell somebody with 50 synced easies and zero logged
 * solves that they are ready to post, then refuse them.
 */
export async function getMyLoggedSolveCount(): Promise<number> {
  const supabase = createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return 0;
  const { count } = await supabase
    .from("problem_events")
    .select("id", { count: "exact", head: true })
    .eq("user_id", user.id)
    .in("kind", ["solved", "revisited"]);
  return count ?? 0;
}

// ── §51 moderation primitives ────────────────────────────────────────────────

/** Report content. One report per person per target; the index enforces it. */
export async function reportFeedEvent(
  eventId: string,
  reason: "spam" | "noise" | "copied" | "bait" | "abuse" | "other",
  detail?: string
): Promise<void> {
  const supabase = createClient();
  // reporter_id must be sent: the insert policy is
  // `with check ((select auth.uid()) = reporter_id)` and no trigger fills it.
  // Omitting it made every Report fail.
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new DataError("feed", "Log in to report.");

  const { error } = await supabase.from("feed_reports").insert({
    reporter_id: user.id,
    event_id: eventId,
    reason,
    detail: detail ?? null,
  });
  if (error) throw new DataError("feed", "Couldn't file that report.", { cause: error });
}

export async function blockUser(blockedId: string): Promise<void> {
  const supabase = createClient();
  // blocker_id, same reason as reporter_id above.
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new DataError("feed", "Log in to block.");
  const { error } = await supabase
    .from("user_blocks")
    .insert({ blocker_id: user.id, blocked_id: blockedId });
  if (error) throw new DataError("feed", "Couldn't block that person.", { cause: error });
}

export async function unblockUser(blockedId: string): Promise<void> {
  const supabase = createClient();
  const { error } = await supabase
    .from("user_blocks")
    .delete()
    .eq("blocked_id", blockedId);
  if (error) throw new DataError("feed", "Couldn't unblock that person.", { cause: error });
}

// ── Legacy readers kept for callers that want plain chronological rows ───────
// §20 ranks usefulness, but the Home panel wants "what just happened", and
// re-deriving that from a usefulness sort would bury the last two minutes.

async function fetchFeed(filter: { squadId?: string; limit?: number }): Promise<FeedEvent[]> {
  const supabase = createClient();
  let query = supabase
    .from("feed_events")
    .select("*, actor:user_id (id, username, avatar_url)")
    .order("created_at", { ascending: false })
    .limit(filter.limit ?? 30);
  if (filter.squadId) query = query.eq("squad_id", filter.squadId);
  const { data, error } = await query;
  if (error) throw new DataError("feed", "Couldn't load feed. Retry.", { cause: error });
  return (data ?? []) as FeedEvent[];
}

export function getSquadFeed(squadId: string, limit = 30): Promise<FeedEvent[]> {
  return fetchFeed({ squadId, limit });
}

/** Recent squad activity for the Home panel (small N, newest first). */
export function getRecentFeed(opts: { squadId: string; limit?: number }): Promise<FeedEvent[]> {
  return fetchFeed({ squadId: opts.squadId, limit: opts.limit ?? 4 });
}

export function getGlobalFeed(limit = 30): Promise<FeedEvent[]> {
  return fetchFeed({ limit });
}
